// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2013, "6-7", [{"author":"Б. Иомдин","question":"В каком слове нет уменьшительного суффикса?","choices":["яблочко","сливка","персик","абрикосик","бананчик"],"key":"В","review":["Суффикс или часть корня","В яблочке, сливке, абрикосике и бананчике узнаём исходные слова «яблоко», «слива», «абрикос» и «банан».","В слове «персик» часть -ик входит в корень: это обычное название плода."]},{"author":"О. Подлесская","question":"В каком словосочетании слово дальний употребляется не в таком смысле, как в остальных?","choices":["дальний лес","дальняя дорога","дальние страны","дальняя деревня","дальний берег"],"key":"Б","review":["Долгая дорога","Дальний лес, страны, деревня и берег находятся далеко от говорящего.","Дальняя дорога — длинный путь, который предстоит проехать или пройти."]},{"author":"О. Подлесская","question":"Он сделал это <em>исподтишка</em>. На какой вопрос отвечает выделенное слово?","choices":["Почему?","Зачем?","Как?","Когда?","Откуда?"],"key":"В","review":["Способ действия","«Исподтишка» значит скрытно, втихомолку.","Слово поясняет, как именно человек это сделал."]},{"author":"О. Подлесская","question":"Описывая внешность человека, вряд ли скажут: У него нос …","choices":["крючком","картошкой","пуговкой","кнопкой","скрепкой"],"key":"Д","review":["Форма носа","Выражения «нос крючком», «картошкой», «пуговкой» и «кнопкой» описывают узнаваемую форму носа.","Сравнение носа со скрепкой для такого описания не принято."]},{"author":"Б. Иомдин и Л. Фёдорова","question":"Какой знак нередко встречается внутри слова?","choices":["равенства","вопросительный","переноса","плюс","восклицательный"],"key":"В","review":["Слово на двух строках","Когда слово не помещается на строке, его можно разделить по правилам переноса.","Знак переноса ставят после первой части слова перед переходом на следующую строку."]},{"author":"А. Сомин","question":"Саша писал сочинение. Первые несколько ________ он написал сразу же, а потом глубоко задумался. Как правильно заполнить пропуск?","choices":["абзацей","абзацев","абзацов","абзатцов","абзатцев"],"key":"Б","review":["Несколько абзацев","После «несколько» нужен родительный падеж множественного числа.","Форма слова «абзац» в этом падеже — «абзацев»."]},{"author":"Б. Иомдин","question":"В какой паре слова не соотносятся по смыслу так, как в остальных?","choices":["добрый ― добряк","толстый ― толстяк","простой ― простак","злой ― злак","чужой ― чужак"],"key":"Г","review":["Случайное созвучие","Добряк — добрый человек, толстяк — толстый, простак — простодушный, чужак — чужой.","Злак — растение, а его название со словом «злой» только случайно созвучно."]},{"author":"Е. Муравенко и А. Панина","question":"Четыре из перечисленных ниже существительных могут записываться одним особым способом, а одно — нет. Какое?","choices":["билет","номер","параграф","процент","доллар"],"key":"А","review":["Слова и знаки","№ заменяет слово «номер», § — «параграф», % — «процент», $ — «доллар».","У слова «билет» нет такого общепринятого знака."]},{"author":"Б. Иомдин","question":"В книге Александры Бруштейн «Дорога уходит в даль», написанной более полувека назад, читаем: У нас всякая комната имеет определённое назначение: в кабинете папа работает, в спальной спят, в столовой едят, в детской ― мы с Сенечкой. Какая из этих комнат теперь чаще называется иначе?","choices":["первая","вторая","третья","четвёртая","все эти комнаты продолжают называться так же"],"key":"Б","review":["Современное название комнаты","«В спальной спят» описывает комнату, предназначенную для сна.","Сегодня такую комнату чаще называют спальней."]},{"author":"Л. Фёдорова","question":"Какая буква русского алфавита не встречается перед согласной?","choices":["ы","й","ё","ь","ъ"],"key":"Д","review":["Перед согласной","Разделительный твёрдый знак пишут перед е, ё, ю и я, например в словах «подъезд» и «объём».","В словах «сыр», «майка», «мёд» и «пальто» перед согласными стоят ы, й, ё и ь. Буква ъ там не употребляется."]},{"author":"И. Иткин и С. Переверзева","question":"В каком из этих предложений подчёркнутый глагол можно написать и с мягким знаком, и без него?","choices":["Павел Иванович, наш новый сотрудник, очень старается всем <u>понрави(т/ть)ся</u>.","Они и рады бы не <u>боя(т/ть)ся</u>, а всё равно немножко страшно.","Женю звали в гости, но она решила, что лучше <u>встрети(т/ть)ся</u> со мной.","Мы уверены, что с ним ничего не <u>случи(т/ть)ся</u>.","Давай он сначала <u>согласи(т/ть)ся</u>, а там посмотрим"],"key":"В","review":["Два прочтения","«Лучше встретиться» — оценка поступка с неопределённой формой глагола.","«Она решила, что лучше встретится со мной» описывает её намерение. У формы третьего лица мягкого знака перед -ся нет."]},{"author":"И. Иткин","question":"Какое из этих выражений точно стоит в том падеже, который оно называет?","choices":["именительный падеж","родительный падеж","дательного падежа","винительного падежа","творительным падежом"],"key":"Д","review":["Название и падеж","«Дательного падежа» стоит в родительном падеже, а «винительного падежа» тоже имеет окончание родительного.","«Творительным падежом» отвечает на вопрос «чем?» и действительно стоит в творительном падеже."]},{"author":"Б. Иомдин","question":"Какое из данных слов женского рода?","choices":["гусли","мысли","мюсли","ясли","никакое"],"key":"Б","review":["Род и число","В словах «гусли», «мюсли» и «ясли» употребляется только множественное число, поэтому род у них не определяют.","У слова «мысли» есть форма единственного числа «мысль», женский род."]},{"author":"Л. Фёдорова","question":"В каком слове буква, обозначающая мягкий шипящий согласный, читается как буква, обозначающая твёрдый шипящий?","choices":["тушь","вещь","ручонка","помощник","тушёнка"],"key":"Г","review":["Звук в слове «помощник»","Твёрдый шипящий [ш] обычно обозначают буквой ш, а мягкий долгий [щ’] — буквой щ.","В слове «помощник» сочетание щн произносится [шн], и щ обозначает твёрдый [ш]."]},{"author":"Н. Валеева","question":"Даны слова: предатель, запредельный, предок, предостаточно, предыдущий. Сколько из них имеют в своём составе приставку пред-?","choices":["одно","два","три","четыре","все пять"],"key":"А","review":["Приставка «пред-»","«Предыдущий» буквально значит «идущий перед»; в нём выделяется приставка пред-.","Сравни «предать» и «предостаточно» с «дать» и «достаточно», «запредельный» с «предел»; в современном слове «предок» предок — корень."]},{"author":"А. Панина","question":"Учитель выписывал на доске слова в два столбика. Какое слово он записал в оба столбика?","choices":["плановый","планерист","дельтаплан","планировать","планомерно"],"key":"Г","review":["Одинаковая форма двух слов","Слова можно сгруппировать вокруг двух значений. Плановый и планомерно связаны с планом действий, планерист и дельтаплан — с полётом.","«Планировать» значит и намечать действия, и лететь с постепенным снижением без тяги двигателя."]},{"author":"Б. Иомдин","question":"В какой паре слова не соотносятся по смыслу так, как в остальных?","choices":["просить ― выпросить","нудить ― вынудить","молить ― вымолить","клянчить ― выклянчить","требовать ― вытребовать"],"key":"Б","review":["Чем закончилось действие","«Выпросить», «вымолить», «выклянчить» и «вытребовать» означают получить желаемое с помощью действия, названного первым глаголом.","«Вынудить» — заставить кого-либо действовать. «Нудить» обычно значит надоедать, а вынудить можно и угрозой."]},{"author":"А. Иткин","question":"Со словами какой части речи обычно не сочетается слово очень?","choices":["с существительными","с прилагательными","с наречиями","с глаголами","слово очень свободно сочетается со всеми перечисленными частями речи"],"key":"А","review":["Сочетания со словом «очень»","Обычны «очень интересный», «очень быстро», «очень хочу».","С существительными «очень» в таком значении обычно напрямую не сочетается."]},{"author":"А. Панина","question":"Не узнать о некотором событии ― значит остаться о нём ...","choices":["... в безвестности","... в недоумении","... в неведении","... в невежестве","... без ведома"],"key":"В","review":["О событии не узнали","«Ведать» раньше значило «знать», а «неведение» — незнание.","Тот, кому ничего не известно о событии, пребывает в неведении."]},{"author":"С. Волков","question":"Каким словом можно продолжить ряд: стойбище, лежбище, убежище?","choices":["рубище","стрельбище","чудище","зрелище","волчище"],"key":"Б","review":["Названия мест","Стойбище — место стоянки, лежбище — место, где лежат животные, убежище — место, где укрываются.","Стрельбище тоже называет место действия: там стреляют. Остальные варианты обозначают предмет, существо или зрелище."]},{"author":"Б. Иомдин","question":"Шестая строчка одного шуточного текста выглядит так:\nольше нет укы Е.\nА как выглядит его шестнадцатая строчка?","choices":["ольше нет укы О","ольше нет укы П","ольш нт укы П","оьш т уы О","ьш т уы О"],"key":"Г","review":["Исчезающие буквы","Начальная строка «Больше нет буквы А». Дальше объявляют очередную букву пропавшей, а все объявленные ранее исчезают из текста.","Шестнадцатая буква О, потому что Ё тоже считается. До О уже исчезли, в частности, Б, В, Е, К и Н. Получается «оьш т уы О»."]},{"author":"Б. Иомдин","question":"В каком примере пропущено название не той цифры, что в остальных?","choices":["Выписывать ________ карандашом по картонке было довольно занятно, как и клеить к этой картонке потом веточки мимозы и бумажные бантики. («Известия»).","Шесть истребителей ушли в море, три встали на крыло и выписали ________. (А. Иличевский).","Он выскакивал на берег, выписывая ________, носился по траве. («Наука и жизнь»).","В таком виде они выглядят настоящими гонщиками. С нетерпением ожидая старта, они выписывают ________ на перроне. («Вокруг света»).","Но в дате «1814» Кручинин почему-то старательно выписал ________ задом наперёд. (Н. Шпанов)"],"key":"Д","review":["След в форме цифры","В первых четырёх примерах пишут или описывают траекторией восьмёрки. Так можно назвать движение, в котором по очереди огибают две петли.","В отрывке Н. Шпанова Кручинин зеркально изобразил четвёрку из даты «1814»."]},{"author":"Л. Фёдорова","question":"Стул, огонь, капля, шаг. С названием какого числа каждое из этих слов употребляется в устойчивых выражениях?","choices":["два","четыре","пять","семь","двенадцать"],"key":"А","review":["Устойчивые выражения","Говорят «сидеть между двух стульев» и «оказаться между двух огней».","«Как две капли воды» означает большое сходство, а «в двух шагах» — близость. Всюду речь о числе два."]},{"author":"А. Пиперски","question":"В русском языке десять гласных букв. Сколько из них могут встречаться в окончаниях?","choices":["шесть","семь","восемь","девять","все десять"],"key":"Г","review":["Гласные в окончаниях","Примеры с разными окончаниями: рука, земля, окно, ружьё, море, столы, кони, несу, читаю.","В этих примерах девять разных гласных. Буква э в обычных русских окончаниях не встречается."]},{"author":"А. Иткин","question":"Какое из следующих утверждений верно?\nГлаголы посадить и высадить...","choices":["всегда являются синонимами","всегда являются антонимами","могут быть синонимами, но не могут быть антонимами","могут быть антонимами, но не могут быть синонимами","могут быть и синонимами, и антонимами"],"key":"Д","review":["Контекст меняет отношение","«Посадить рассаду» и «высадить рассаду» могут означать одно действие.","«Посадить пассажира» в автобус и «высадить пассажира» из него — противоположные действия."]},{"author":"Н. Валеева","question":"Даны слова: паводок, пагубный, падчерица, пасынок. Сколько из них содержат (или содержали раньше) приставку па-?","choices":["ни одного","одно","два","три","четыре"],"key":"Д","review":["Историческая приставка","В «пасынке» и «падчерице» узнаются «сын» и «дочь». В «паводке» видна связь со словом «вода».","«Пагубный» образовано от «пагуба», где историческая па- соединялась с основой со значением гибели. Приставка была во всех четырёх."]},{"author":"Е. Холодова","question":"Один маленький мальчик произносит звук [й] не только в тех словах, где этот звук действительно есть, но и вместо [р] и [р’]. Сколько всего разных слов он может иметь в виду, когда говорит «кьюк» и «як»?","choices":["два","три","четыре","пять","шесть"],"key":"В","review":["Замена звука и оглушение","После замены [р] и [р’] на [й] «крюк» и «круг» могут звучать одинаково. Конечный [г] в слове «круг» оглушается до [к].","«Як» мог означать как «як», где [й] был изначально, так и «рак». Всего четыре слова."]},{"author":"Л. Фёдорова","question":"Польский и русский языки родственны. По-польски ― Kopciuszek (Копчушек), а по-русски ― ...","choices":["Золушка","Белоснежка","Дюймовочка","Царевна-лягушка","Курочка Ряба"],"key":"А","review":["Имя сказочной героини","Польское Kopciuszek связано с копотью: так прозвали героиню, которая жила у очага.","В русском имени той же героини отражено слово «зола»: Золушка."]},{"author":"Е. Муравенко","question":"Какие утверждения верны? Все нарицательные существительные, оканчивающиеся на -о или -е, 1) склоняются; 2) неодушевлённые; 3) среднего рода.","choices":["все","только 2","только 3","2 и 3","никакие не верны"],"key":"Д","review":["Три контрпримера","«Метро» оканчивается на -о и не склоняется. «Животное» оканчивается на -е и может быть одушевлённым: «вижу животных».","Слово «кофе» оканчивается на -е, но в книжной норме оно мужского рода. Каждое из трёх утверждений имеет исключение."]},{"author":"А. Сомин","question":"Даны арабские слова, записанные русскими буквами: тафтаху ‘ты открываешь’, йафтахууна ‘они открывают’, йафтаху ‘он открывает’. Как с арабского языка переводится слово ташрабууна?","choices":["‘ты пьёшь’","‘он пьёт’","‘она пьёт’","‘вы пьёте’","‘они пьют’"],"key":"Г","review":["Арабские лицо и число","«Тафтаху» и «йафтаху» различаются началом та-/йа-. В приведённых формах та- соответствует «ты», а йа- — «он» и «они».","Конец -ууна отличает множественное число. Та- и -ууна вместе дают «вы», а основа здесь означает «пить»."]}], {"year":2013,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2013.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
